def solve(n: int) -> int:
    """Return the count of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes up to n-1.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit + 1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

def solve(intervals):
    """Merge all overlapping intervals and return them as a sorted list of
    non-overlapping intervals covering the same ranges. The output intervals
    use the same container type as the input intervals (list or tuple).
    """
    if not intervals:
        return []
    items = sorted(intervals, key=lambda iv: iv[0])
    merged = []
    cur_s, cur_e = items[0]
    for s, e in items[1:]:
        if s <= cur_e:
            if e > cur_e:
                cur_e = e
        else:
            merged.append((cur_s, cur_e))
            cur_s, cur_e = s, e
    merged.append((cur_s, cur_e))
    proto = type(items[0])
    return [proto(iv) for iv in merged]

