def solve(s: str) -> int:
    """Convert a Roman numeral string to an integer.
    Supports the standard symbols I, V, X, L, C, D, M with subtractive notation.
    The input is assumed to be a valid Roman numeral (uppercase or lowercase).
    """
    if not s:
        return 0
    # Mapping of single symbols to values
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    # Process from right to left
    for ch in reversed(s.upper()):
        val = values.get(ch, 0)
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total

