from collections import deque

def solve(grid):
    n = len(grid)
    m = len(grid[0]) if n else 0
    if n == 0 or m == 0 or grid[0][0] != 0 or grid[n - 1][m - 1] != 0:
        return -1
    dist = {(0, 0): 0}
    q = deque([(0, 0)])
    while q:
        r, c = q.popleft()
        if (r, c) == (n - 1, m - 1):
            return dist[(r, c)]
        d = dist[(r, c)]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 0 and (nr, nc) not in dist:
                dist[(nr, nc)] = d + 1
                q.append((nr, nc))
    return -1

